<?php
$folderChildren = [];
foreach ($folders as $folder) $folderChildren[(int) ($folder['parent_id'] ?? 0)][] = $folder;
$serviceChildren = [];
foreach ($services as $service) $serviceChildren[(int) ($service['folder_id'] ?? 0)][] = $service;
$typesById = [];
foreach ($balanceTypes as $type) $typesById[(int) $type['id']] = $type;
$selectedFolder = null;
foreach ($folders as $folder) if ((int) $folder['id'] === $selectedFolderId) $selectedFolder = $folder;
$orderedFolders = [];
$flattenFolders = static function (int $parent, int $depth) use (&$flattenFolders, &$orderedFolders, $folderChildren): void {
    foreach ($folderChildren[$parent] ?? [] as $folder) { $folder['depth'] = $depth; $orderedFolders[] = $folder; $flattenFolders((int) $folder['id'], $depth + 1); }
};
$flattenFolders(0, 0);
?>
