            <div class="class-tree__classes"><?php foreach ($serviceChildren[0] ?? [] as $item): ?><div class="class-tree__class-row"><a class="class-tree__class" draggable="true" data-drag-class="<?= (int) $item['id'] ?>" data-source-folder="0" href="<?= e(url('/education/services#service-row-' . $item['id'])) ?>"><span class="class-tree__class-icon"><?= icon('file', 15) ?></span><span><strong><?= e($item['name']) ?></strong><small><?= $item['status'] === 'active' ? 'Доступна' : 'Скрыта' ?></small></span></a><button type="button" class="class-move-button" data-move-class="<?= (int) $item['id'] ?>" data-source-folder="0" data-class-name="<?= e($item['name']) ?>" aria-label="Переместить услугу <?= e($item['name']) ?>">⋮</button></div><?php endforeach; ?></div>
        </div>
        <div data-collapsible-tree="services">
        <?php
        $renderFolders = static function (int $parent) use (&$renderFolders, $folderChildren, $serviceChildren, $selectedFolderId): void {
            foreach ($folderChildren[$parent] ?? [] as $folder): $id = (int) $folder['id']; $items = $serviceChildren[$id] ?? [];
        ?>
            <section class="class-tree__branch <?= $id === $selectedFolderId ? 'is-active' : '' ?>" data-drop-folder="<?= $id ?>" data-parent-folder="<?= $parent ?>">
                <div class="class-tree__folder-row"><a class="class-tree__folder <?= $id === $selectedFolderId ? 'is-active' : '' ?>" draggable="true" data-drag-folder="<?= $id ?>" href="<?= e(url('/education/services?folder_id=' . $id)) ?>"><span class="folder-mark"><?= icon('folder', 19) ?></span><span><strong><?= e($folder['name']) ?></strong><small><?= count($items) ?> услуг</small></span></a><button class="class-tree__toggle" type="button" data-folder-toggle aria-expanded="true" aria-label="Свернуть папку <?= e($folder['name']) ?>" title="Свернуть папку"><?= icon('chevron-right', 15) ?></button><button type="button" class="class-move-button" data-move-folder-id="<?= $id ?>" data-folder-name="<?= e($folder['name']) ?>" aria-label="Переместить папку <?= e($folder['name']) ?>">⋮</button></div>
                <?php if (!empty($folderChildren[$id])): ?><div class="class-tree__children"><?php $renderFolders($id); ?></div><?php endif; ?>
                <div class="class-tree__classes"><?php foreach ($items as $item): ?><div class="class-tree__class-row"><a class="class-tree__class" draggable="true" data-drag-class="<?= (int) $item['id'] ?>" data-source-folder="<?= $id ?>" href="<?= e(url('/education/services?folder_id=' . $id . '#service-row-' . $item['id'])) ?>"><span class="class-tree__class-icon"><?= icon('file', 15) ?></span><span><strong><?= e($item['name']) ?></strong><small><?= $item['status'] === 'active' ? 'Доступна' : 'Скрыта' ?></small></span></a><button type="button" class="class-move-button" data-move-class="<?= (int) $item['id'] ?>" data-source-folder="<?= $id ?>" data-class-name="<?= e($item['name']) ?>" aria-label="Переместить услугу <?= e($item['name']) ?>">⋮</button></div><?php endforeach; ?><?php if (!$items && empty($folderChildren[$id])): ?><span class="class-tree__empty">Услуг пока нет</span><?php endif; ?></div>
            </section>
        <?php endforeach; }; $renderFolders(0); ?>
