    <main class="catalog-content">
        <section class="folder-heading panel"><span class="folder-heading__icon"><?= icon('folder', 28) ?></span><div><p class="page-eyebrow">Выбранная папка</p><h2><?= e($selectedFolder['name'] ?? 'Без папки') ?></h2><p><?= count($serviceChildren[$selectedFolderId] ?? []) ?> услуг</p></div></section>
        <section class="panel services-panel"><div class="services-toolbar"><button type="button" class="button button--primary" id="service-add"><?= icon('plus', 17) ?> Добавить услугу</button><label class="services-search"><input id="service-search" placeholder="Поиск по названию" aria-label="Поиск по названию"></label><label><input type="checkbox" id="show-inactive"> Скрытые</label></div>
        <div class="data-table-wrap"><table class="data-table stage-table services-list"><thead><tr><th>Наименование</th><th>Начисления</th><th>Стоимость</th><th>Статус</th><th><span class="sr-only">Действия</span></th></tr></thead><tbody>
        <?php foreach ($serviceChildren[$selectedFolderId] ?? [] as $service):
            $details = json_decode($service['service_data'] ?? '', true) ?: []; $totals = [];
            foreach ($details['allocations'] ?? [] as $allocation) foreach ($allocation['balances'] ?? [] as $typeId => $value) if ((float) $value > 0) $totals[(int) $typeId] = ($totals[(int) $typeId] ?? 0) + (float) $value;
        ?><tr id="service-row-<?= (int) $service['id'] ?>" class="service-item" data-service="<?= e(json_encode($service, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_QUOT | JSON_HEX_AMP)) ?>"><td><strong><?= e($service['name']) ?></strong></td><td><div class="balance-strip"><?php foreach ($totals as $typeId => $amount): $type = $typesById[$typeId] ?? null; if (!$type) continue; ?><span class="balance-chip" title="<?= e($type['name']) ?>"><b style="--chip-color:<?= e($type['color']) ?>"><?= e($type['code']) ?></b><span><?= e(rtrim(rtrim(number_format($amount, 2, ',', ' '), '0'), ',')) ?> <?= e($type['unit'] === 'hours' ? 'ч' : ($type['unit'] === 'money' ? '₽' : '')) ?></span></span><?php endforeach; ?><?php if (!$totals): ?><span class="table-subline">Не настроены</span><?php endif; ?></div></td><td><?= e(number_format((float) $service['price'], 2, ',', ' ')) ?> ₽</td><td><span class="status-pill status-pill--<?= $service['status'] === 'active' ? 'active' : 'blocked' ?>"><i></i><?= $service['status'] === 'active' ? 'Доступна' : 'Скрыта' ?></span></td><td><button type="button" class="table-action" data-service-edit aria-label="Редактировать <?= e($service['name']) ?>" title="Редактировать"><?= icon('edit', 17) ?></button></td></tr><?php endforeach; ?>
        <?php if (empty($serviceChildren[$selectedFolderId])): ?><tr><td colspan="5"><div class="empty-inline">В этой папке пока нет услуг.</div></td></tr><?php endif; ?>
        </tbody></table></div></section>
